/**
 * Verifies that every canonical premium component ID has an entry in
 * src/data/sourceCode.json. Fails the MCP build if any are missing.
 *
 * Reads the canonical premium list from src/data/premiumComponents.json
 * (generated by scripts/sync-frontend-data.mjs).
 * Reads coverage from src/data/sourceCode.json.
 *
 * Usage: node scripts/check-source-coverage.mjs
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const MCP_DATA = path.join(__dirname, '..', 'src', 'data');

// Load canonical premium IDs (generated by sync-frontend-data.mjs from frontend premiumComponents.ts)
const premPath = path.join(MCP_DATA, 'premiumComponents.json');
if (!fs.existsSync(premPath)) {
  console.error('check-source-coverage: missing', premPath, '(run: node scripts/sync-frontend-data.mjs)');
  process.exit(1);
}
const premiumIds = JSON.parse(fs.readFileSync(premPath, 'utf8'));
if (!Array.isArray(premiumIds) || premiumIds.length === 0) {
  console.error('check-source-coverage: invalid or empty premium list in', premPath);
  process.exit(1);
}

// Load sourceCode.json
const sourceCode = JSON.parse(fs.readFileSync(path.join(MCP_DATA, 'sourceCode.json'), 'utf8'));
const sourceIds = new Set(Object.keys(sourceCode));

// Check coverage
const missing = premiumIds.filter((id) => !sourceIds.has(id));

if (missing.length > 0) {
  console.error(`\ncheck-source-coverage FAILED: ${missing.length} premium component(s) missing from sourceCode.json:`);
  for (const id of missing) console.error(`  - ${id}`);
  console.error('\nRun: node scripts/sync-frontend-data.mjs');
  console.error('If the ids are not in the catalog, ensure their PascalCase .tsx file exists in frontend/src/components/ui/\n');
  process.exit(1);
}

console.log(`check-source-coverage OK: ${premiumIds.length}/${premiumIds.length} premium ids present in sourceCode.json (${Object.keys(sourceCode).length} total entries)`);
